INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginne ich hier ohne Risiken zu prüfen?', 2, '[{"text": "Nein", "correct": true, "because": "Risikoanalyse ist erster Schritt"}, {"text": "Ja", "correct": false, "because": "Risikofokus zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt startet jeden Zyklus?', 3, '[{"text": "Risikoanalyse", "correct": true, "because": "Risiken zuerst identifizieren"}, {"text": "Prototyping", "correct": false, "because": "Folgt Analyse"}, {"text": "Bewertung", "correct": false, "because": "Schließt Zyklus ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu jedem Zyklus?', 5, '[{"text": "Risikoanalyse", "correct": true, "because": "Risiken erkennen"}, {"text": "Prototyping", "correct": true, "because": "Lösungen testen"}, {"text": "Einmalige Planung", "correct": false, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bewertung schließt den Zyklus. b) Prototyping ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototyping essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich in diesen Zyklen?', 4, '[{"text": "Risikoanalyse", "correct": false, "because": "Kern des Modells"}, {"text": "Bewertung", "correct": false, "because": "Ergebnisse prüfen"}, {"text": "Lineare Schritte", "correct": true, "because": "Iterativ aufgebaut"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal bewertet?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus wird bewertet"}, {"text": "Ja", "correct": false, "because": "Iterativer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich, um Lösungen zu testen?', 3, '[{"text": "Prototyping", "correct": true, "because": "Prototypen erstellen"}, {"text": "Risikoanalyse", "correct": false, "because": "Risiken erkennen"}, {"text": "Bewertung", "correct": false, "because": "Ergebnisse prüfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen sichern das Projekt ab?', 5, '[{"text": "Risikoanalyse", "correct": true, "because": "Probleme früh erkennen"}, {"text": "Bewertung", "correct": true, "because": "Fortschritt überprüfen"}, {"text": "Einmalige Tests", "correct": false, "because": "Zyklisch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Risikoanalyse ist der Start. b) Bewertung ist unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bewertung essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Prototyping", "correct": false, "because": "Lösungen testen"}, {"text": "Risikoanalyse", "correct": false, "because": "Risiken im Fokus"}, {"text": "Feste Phasen", "correct": true, "because": "Iterativ flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Prototyping hier einmalig?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus nutzt Prototypen"}, {"text": "Ja", "correct": false, "because": "Iterativer Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte fördern iterative Absicherung?', 4, '[{"text": "Risikoanalyse", "correct": true, "because": "Risiken früh angehen"}, {"text": "Prototyping", "correct": true, "because": "Lösungen validieren"}, {"text": "Lineare Entwicklung", "correct": false, "because": "Zyklisch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Analyse arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Risikoanalyse ist Kern"}, {"text": "Ja", "correct": false, "because": "Risiken im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in jedem Zyklus?', 3, '[{"text": "Risikoanalyse", "correct": true, "because": "Risiken zuerst klären"}, {"text": "Bewertung", "correct": false, "because": "Schließt Zyklus ab"}, {"text": "Fertigstellung", "correct": false, "because": "Ende des Projekts"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prototyping testet Lösungen. b) Risikoanalyse ist selten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Analyse in jedem Zyklus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Zyklen?', 5, '[{"text": "Risikoreduktion", "correct": true, "because": "Analyse frühzeitig"}, {"text": "Validierte Lösungen", "correct": true, "because": "Prototyping prüft"}, {"text": "Einmalige Iteration", "correct": false, "because": "Wiederholte Schritte"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Risikoanalyse", "correct": false, "because": "Kernprinzip"}, {"text": "Prototyping", "correct": false, "because": "Testen zentral"}, {"text": "Statische Phasen", "correct": true, "because": "Iterativ flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Bewertung hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus wird geprüft"}, {"text": "Ja", "correct": false, "because": "Bewertung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal Prototypen erstelle?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus nutzt Prototypen"}, {"text": "Ja", "correct": false, "because": "Iterative Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach der Analyse?', 4, '[{"text": "Prototyping", "correct": true, "because": "Lösungen testen"}, {"text": "Bewertung", "correct": false, "because": "Schließt Zyklus"}, {"text": "Risikoanalyse", "correct": false, "because": "Start des Zyklus"}]');
